style.css:
@-moz-document domain("pinterest.com") {
html, body {
    height: 100%;
    background: #000 !important; /* fondo negro para bordes */
  }

  /* Fondo de leopardo centrado solo dentro del contenido */
  body::before {
    content: "";
    position: fixed;
    top: 40px; /* margen superior para que se vea el borde negro */
    bottom: 40px; /* margen inferior */
    left: 40px; /* borde izquierdo negro */
    right: 40px; /* borde derecho negro */
    background-image: url("https://static4.depositphotos.com/1019221/338/i/450/depositphotos_3382879-stock-illustration-leopard-background.jpg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    border-radius: 40px; /* redondea las esquinas del fondo */
    box-shadow: 0 0 20px rgba(0,0,0,0.8);
    z-index: -9999;
    pointer-events: none;
  }

  /* Hacer transparentes los contenedores principales */
  #__next, #root, .App, .AppContainer, [data-test-id="app-root"], div[role="main"] {
    background: transparent !important;
  }

  /* Cabecera y buscador transparentes para dejar ver el fondo */
  header, .Header, .topNav, [data-test-id="header"], input[type="search"], .SearchBox, .searchBox {
    background: transparent !important;
    color: #fff !important;
    border: none !important;
  }

  /* Textos del header en blanco */
  header *, .Header *, .topNav *, .SearchBox * {
    color: #fff !important;
    fill: #fff !important;
  }

  input[type="search"]::placeholder { color: #eee !important; }

  /* Pines y tarjetas transparentes */
  .Pin, .Board, .gridItem, .searchResult {
    background: transparent !important;
  }

  /* Quita sombras o bordes blancos molestos */
  * {
    box-shadow: none !important;
  }
}
